      const connector = type.connectors.find((p) => p.guid === connectorGuid);
      if (connector) return connector;
    }

    if (type.parent?.guid) {
      const parentType = getType(type.parent.guid);
      const connector = getConnector(parentType, connectorGuid);
      if (connector) return connector;
