 **/
export type Constraint = (ctx: ValidationContext) => Problem[];

/**
 * Interface defining ValidationConfig structure.
 *
 *  * [👤compose📚js💻compose🔖kit🔖validation🔖validationcontextengine🛠️validationconfig](composerepo://p/u/compose/b/l/js/f/compose.ts/s/Kit/s/Validation/s/Validation%20context%20&%20engine/d/i/ValidationConfig)
 **/
export interface ValidationConfig {
  constraints?: Constraint[];
}

/**
 * Definition of defaultConstraints.
 *
 *  * [👤compose📚js💻compose🔖kit🔖validation🔖validationcontextengine🛠️defaultconstraints](composerepo://p/u/compose/b/l/js/f/compose.ts/s/Kit/s/Validation/s/Validation%20context%20&%20engine/d/i/defaultConstraints)
 **/
export let defaultConstraints: Constraint[] = [];

/**
 * Validates Kit against constraints.
*
* MUST check all constraints and return problems.
*
*  * [👤compose📚js💻compose🔖kit🔖validation🔖validationcontextengine🪨validatekit](composerepo://p/u/compose/b/l/js/f/compose.ts/s/Kit/s/Validation/s/Validation%20context%20&%20engine/d/i/validateKit)
**/
export const validateKit = (kit: Kit, cfg: ValidationConfig = {}): ValidationResult => {
  const ctx = buildValidationContext(kit);
  const constraints = cfg.constraints ?? defaultConstraints;
  return { problems: constraints.flatMap((constraint) => constraint(ctx)) };
};

