 **/
export const composeMakeFix = (ctx: ValidationContext, title: string, mutate: (clone: Kit) => void): Fix => {
  const clone = JSON.parse(serializeKit(ctx.kit)) as Kit;
  mutate(clone);
  const diff = getKitDiff(ctx.kit, clone);
  return { title, diff };
};

