 **/
export const findModel = (models: Model[], tagGuids: string[]): Model => {
  const indices = models.map((r) =>
    jaccard(
      r.tags?.map((t) => t.guid),
      tagGuids,
    ),
  );
  const maxIndex = Math.max(...indices);
  const maxIndexIndex = indices.indexOf(maxIndex);
  return models[maxIndexIndex];
};

