 **/
export const getAllTagGuidsFromModels = (models: Model[]): string[] => {
  const tagsSet = new Set<string>();
  models.forEach((r) => {
    toArray(r.tags).forEach((tag) => tagsSet.add(tag.guid));
  });
  return Array.from(tagsSet).sort();
};

/**
