// cachedSqlJs holds the data fields for a cachedSqlJs record.
let cachedSqlJs: any = null;
// [👤compose📚js💻compose🔖kit🔖kitimport🔖export🪨getsqljs](composerepo://p/u/compose/b/l/js/f/compose.ts/s/Kit/s/Kit%20Import/Export/d/i/getSqlJs)
// getSqlJs holds the data fields for a getSqlJs record.
const getSqlJs = async () => {
  if (!cachedSqlJs) {
    const initSqlJs = (await import("sql.js")).default;
    try {
      const isNode = typeof process !== "undefined" && process.versions?.node;
      if (isNode) {
        const path = await import("path");
        const url = await import("url");
        const __dirname = path.dirname(url.fileURLToPath(import.meta.url));
        cachedSqlJs = await initSqlJs({
          locateFile: (file: string) => path.join(__dirname, "public", file),
        });
      } else {
        cachedSqlJs = await initSqlJs({
          locateFile: (file: string) => `/${file}`,
        });
      }
    } catch (error) {
      console.error("Failed to initialize sql.js:", error);
      throw new Error("Failed to load SQLite database library.");
    }
  }
  return cachedSqlJs;
};

const buildFolderPath = (kit: Kit, folderGuid: string): string => {
  if (!kit.folders) return "";
  for (const f of kit.folders) {
    if (f.guid === folderGuid) {
      if (f.parent) {
        const parentPath = buildFolderPath(kit, f.parent.guid);
        if (parentPath) return `${parentPath}/${f.name}`;
      }
      return f.name;
    }
  }
  return "";
};

const buildFilePath = (kit: Kit, file: File): string => {
  if (file.folder) {
    const folderPath = buildFolderPath(kit, file.folder.guid);
    if (folderPath) return `${folderPath}/${file.name}`;
  }
  return file.name;
};

