  // Serialize kit without blob data
  const kitForZip: Kit = {
    ...kit,
    files: kit.files?.map((f) => {
      const { blob, ...rest } = f;
      return rest;
    }),
  };

  const kitJson = serializeKit(kitForZip);

  const zip = new JSZip();
  zip.file("kit.json", kitJson);

  // Write actual files from blob data
  if (kit.files) {
    for (const file of kit.files) {
      if (file.blob) {
        const binary = atob(file.blob);
        const bytes = new Uint8Array(binary.length);
        for (let i = 0; i < binary.length; i++) {
          bytes[i] = binary.charCodeAt(i);
        }
        const filePath = buildFilePath(kit, file);
        zip.file(filePath, bytes);
      }
    }
  }

  return await zip.generateAsync({ type: "blob" });
};

