            Unit = Unit,
            Location = Location,
            Models = new ModelsDiff { Added = new List<Model>(), Removed = new List<ModelId>(), Updated = Models.Select(m => new ModelDiffUpdate { Model = m, Diff = m.CreateDiff() }).ToList() },
