            Icon = diff.Icon ?? Icon,
            Image = diff.Image ?? Image,
            Location = diff.Location ?? Location,
            Unit = diff.Unit ?? Unit,
            ActiveLayer = diff.ActiveLayer ?? ActiveLayer,
